export function bindControls(api) {
  const status = document.querySelector('#status');
  const stats = document.querySelector('#stats');
  const updateStats = () => {
    const s = api.getStats();
    stats.textContent = `lightCount: ${s.lightCount}\nexposure: ${s.exposure.toFixed(2)}\nintensity: ${s.intensity.toFixed(2)}`;
  };
  document.querySelectorAll('#controls input[data-key]').forEach((input) => {
    input.addEventListener('input', () => {
      try { api.setParams({ [input.dataset.key]: parseFloat(input.value) }); updateStats(); }
      catch (err) { status.textContent = `error: ${err.message || err}`; }
    });
  });
  const btn = document.querySelector('#btn-capture');
  btn.addEventListener('click', () => {
    try {
      const url = api.capture();
      const a = document.createElement('a');
      a.href = url; a.download = 'deferred-light-lab.png'; a.click();
    } catch (err) { status.textContent = `error: ${err.message || err}`; }
  });
  updateStats();
}
```

Note controls.js currently has `export function bindControls(api) {}` — replace.

